package common

import (
	"context"
	"fmt"
	"math/big"

	"github.com/ethereum/go-ethereum/common"
	"github.com/ethereum/go-ethereum/crypto"
)

// Contract creation bytecode ported verbatim from the legacy Rust harness
// (crates/tests/operations/contracts.rs). Keeping the exact init code preserves
// the deployed runtime code and event topics the scenarios assert against.
const (
	// ERC20BytecodeHex is an OpenZeppelin-style ERC20 (MyToken/MTK) that mints its
	// initial supply to the deployer.
	ERC20BytecodeHex = ""

	// ContractBBytecodeHex is a minimal counter contract exposing dummy()/counter/getCounter().
	ContractBBytecodeHex = ""

	// ContractABytecodeHex takes ContractB's address in its constructor and its
	// triggerCall() invokes ContractB.dummy() while incrementing a call counter.
	ContractABytecodeHex = ""

	// ContractCBytecodeHex exposes setValue(uint256)/getValue()/value.
	ContractCBytecodeHex = ""

	// SimpleStorageBytecodeHex takes an initial value in its constructor and exposes
	// setValue/getValue/value plus creator/getCreator.
	SimpleStorageBytecodeHex = ""
)

// MethodSelector returns the 4-byte function selector for a Solidity signature
// such as "transfer(address,uint256)".
func MethodSelector(signature string) []byte {
	return crypto.Keccak256([]byte(signature))[:4]
}

// padWord left-pads b to a 32-byte ABI word.
func padWord(b []byte) []byte {
	word := make([]byte, 32)
	copy(word[32-len(b):], b)
	return word
}

// encodeAddress ABI-encodes an address as a 32-byte word.
func encodeAddress(a common.Address) []byte { return padWord(a.Bytes()) }

// encodeUint256 ABI-encodes a uint256 as a 32-byte word.
func encodeUint256(v *big.Int) []byte { return padWord(v.Bytes()) }

// encodeBool ABI-encodes a bool as a 32-byte word.
func encodeBool(b bool) []byte {
	if b {
		return padWord([]byte{1})
	}
	return padWord([]byte{0})
}

// Calldata builders for the fixtures and gasless whitelist, ported from the Rust
// harness's inline sol! encodings.
func EncodeERC20Transfer(to common.Address, amount *big.Int) []byte {
	out := MethodSelector("transfer(address,uint256)")
	out = append(out, encodeAddress(to)...)
	out = append(out, encodeUint256(amount)...)
	return out
}

func EncodeERC20BalanceOf(owner common.Address) []byte {
	return append(MethodSelector("balanceOf(address)"), encodeAddress(owner)...)
}

func EncodeTriggerCall() []byte { return MethodSelector("triggerCall()") }

func EncodeGetValue() []byte { return MethodSelector("getValue()") }

func EncodeSetGaslessEnabled(enabled bool) []byte {
	return append(MethodSelector("setGaslessEnabled(bool)"), encodeBool(enabled)...)
}

func EncodeSetFullyGaslessTarget(target common.Address, enabled bool, gasLimit *big.Int) []byte {
	out := MethodSelector("setFullyGaslessTarget(address,bool,uint256)")
	out = append(out, encodeAddress(target)...)
	out = append(out, encodeBool(enabled)...)
	out = append(out, encodeUint256(gasLimit)...)
	return out
}

// DeployedContracts holds the addresses of the fixtures a scenario deploys, in
// the same set the Rust try_deploy_contracts helper produced.
type DeployedContracts struct {
	ContractA common.Address
	ContractB common.Address
	ContractC common.Address
	ERC20     common.Address
}

// DeployStandardFixtures deploys ContractB, ContractA (referencing B), ContractC
// and the ERC20 from acct and waits for each to be mined. It ports the fixture
// set of the Rust try_deploy_contracts helper.
func (a *Account) DeployStandardFixtures(ctx context.Context, c *DevnetClient, gasLimit uint64, gasFeeCap *big.Int) (*DeployedContracts, error) {
	out := &DeployedContracts{}

	deploy := func(name string, initCode []byte) (common.Address, error) {
		h, addr, err := a.Deploy(ctx, c, initCode, gasLimit, gasFeeCap)
		if err != nil {
			return common.Address{}, fmt.Errorf("deploy %s: %w", name, err)
		}
		if _, err := c.WaitForTxMined(ctx, h); err != nil {
			return common.Address{}, fmt.Errorf("await %s: %w", name, err)
		}
		return addr, nil
	}

	var err error
	if out.ContractB, err = deploy("ContractB", common.FromHex(ContractBBytecodeHex)); err != nil {
		return nil, err
	}
	aInit := append(common.FromHex(ContractABytecodeHex), encodeAddress(out.ContractB)...)
	if out.ContractA, err = deploy("ContractA", aInit); err != nil {
		return nil, err
	}
	if out.ContractC, err = deploy("ContractC", common.FromHex(ContractCBytecodeHex)); err != nil {
		return nil, err
	}
	if out.ERC20, err = deploy("ERC20", common.FromHex(ERC20BytecodeHex)); err != nil {
		return nil, err
	}
	return out, nil
}
